referenceSolutionTemplate:
#include <stdio.h>

void show(const char *label, int value) {
    unsigned char x = (unsigned char)value;
    printf("%s = ", label);
    for (int i = 7; i >= 0; i--) {
        printf("%d", (x >> i) & 1);
    }
    printf("\n");
}

int main(void) {
    show("{a}", {a});
    show("{b}", {b});
    show("{a} & {b}", {a} & {b});
    show("{a} | {b}", {a} | {b});
    show("{a} ^ {b}", {a} ^ {b});
    return 0;
}
